SELECT USERINFO_ID USERINFOID, OPENID OPENID, ACTIVITY_ID ACTIVITYID, USER_FULL_NAME USERFULLNAME, ADDRESS ADDRESS, MOBILE MOBILE, ITEM_KEY ITEMKEY, ITEM_VALUE ITEMVALUE, CREATED_BY CREATEDBY, TO_CHAR(CREATED_DATE,'yyyy-mm-dd hh24:mi:ss') CREATEDTIME, TO_DATE(TO_CHAR(UPDATED_DATE,'yyyy-mm-dd hh24:mi:ss'),'yyyy-mm-dd hh24:mi:ss') UPDATEDDATE, UPDATED_BY UPDATEDBY FROM CMWA_WX_ACTIVITY_USERINFO T WHERE T.ACTIVITY_ID = #{activityId,jdbcType=VARCHAR}
AND T.MOBILE = #{mobile,jdbcType=VARCHAR}
AND T.ITEM_KEY = #{itemKey,jdbcType=INTEGER}
ORDER BY T.CREATED_DATE DESC

